LEAD_DEMO_HTML = """<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Relay — Human-Approved Lead Agent</title>
  <style>
    :root{--bg:#f5f1e8;--ink:#18201d;--muted:#65706b;--line:#d8d3c7;--card:#fffdf7;--lime:#c9f45b;--green:#174c3c;--orange:#ff8c54}
    *{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#f7f4ec 55%,#e6f0d5);color:var(--ink);font:15px/1.5 Inter,ui-sans-serif,system-ui,sans-serif;min-height:100vh}.shell{width:min(1160px,calc(100% - 32px));margin:auto;padding:28px 0 52px}.nav,.hero,.row,.head{display:flex;align-items:center}.nav{justify-content:space-between;margin-bottom:50px}.brand{font-size:18px;font-weight:900}.brand mark{background:var(--lime);padding:4px 8px;border-radius:8px}.nav a{color:var(--ink);text-decoration:none;font-size:13px;margin-left:18px}
    .hero{justify-content:space-between;gap:30px;margin-bottom:28px}.eyebrow{font-size:12px;font-weight:850;letter-spacing:.14em;color:var(--green);text-transform:uppercase}h1{font-size:clamp(38px,5vw,64px);letter-spacing:-.05em;line-height:1;margin:8px 0 14px;max-width:760px}.hero p{max-width:670px;color:var(--muted);font-size:17px}.guard{border:1px solid var(--green);border-radius:18px;padding:16px 18px;min-width:220px;background:#f8ffe8}.guard b{display:block;color:var(--green);font-size:13px}.guard span{font-size:12px;color:var(--muted)}
    .layout{display:grid;grid-template-columns:.88fr 1.12fr;gap:18px}.card{background:rgba(255,253,247,.93);border:1px solid var(--line);border-radius:22px;padding:23px;box-shadow:0 24px 60px rgba(41,54,47,.10)}.head{justify-content:space-between;margin-bottom:18px}.head h2{font-size:16px;margin:0}.badge{font-size:11px;background:#e7ecdf;padding:6px 9px;border-radius:999px;color:var(--green);font-weight:800;text-transform:uppercase}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.wide{grid-column:1/-1}label{display:block;color:var(--muted);font-size:11px;font-weight:750;letter-spacing:.05em;margin-bottom:5px;text-transform:uppercase}input,textarea{width:100%;border:1px solid var(--line);background:#fff;border-radius:10px;padding:11px 12px;color:var(--ink);font:inherit;outline:none}input:focus,textarea:focus{border-color:var(--green)}textarea{min-height:76px;resize:vertical}.check{display:flex;gap:8px;align-items:center;color:var(--ink);font-size:13px}.check input{width:auto}.primary{width:100%;margin-top:14px;border:0;border-radius:12px;background:var(--green);color:white;padding:14px;font-weight:850;cursor:pointer}.primary:hover{background:#0f3b2e}.primary:disabled{opacity:.6;cursor:wait}
    .result{min-height:430px}.empty{height:365px;display:grid;place-items:center;text-align:center;color:var(--muted)}.empty b{display:block;color:var(--ink);font-size:20px;margin-bottom:6px}.score{display:flex;align-items:center;gap:16px;padding:18px;border-radius:16px;background:var(--green);color:white}.score strong{font-size:45px;line-height:1}.score small{display:block;color:#bad6ca}.reasons{display:flex;flex-wrap:wrap;gap:7px;margin:14px 0}.reason{background:#edf5da;border:1px solid #d7e9ad;color:#35512b;padding:6px 9px;border-radius:999px;font-size:11px}.draft{padding:15px;border-left:3px solid var(--orange);background:#fff7ed;border-radius:0 12px 12px 0;font-size:13px;color:#5e554c}.workflow{display:flex;gap:6px;align-items:center;margin:15px 0}.node{font-size:10px;border:1px solid var(--line);padding:7px 8px;border-radius:8px;background:#fff}.node.on{background:var(--lime);border-color:#acd541;font-weight:800}.arrow{color:#9da69f}.actions{display:grid;grid-template-columns:1fr 1fr;gap:9px}.actions button{border:1px solid var(--green);border-radius:10px;padding:11px;background:#fff;color:var(--green);font-weight:800;cursor:pointer}.actions .approve{background:var(--green);color:#fff}.audit{margin-top:14px;border-top:1px solid var(--line);padding-top:12px}.audit-item{font-size:11px;color:var(--muted);padding:4px 0}.audit-item b{color:var(--ink);text-transform:capitalize}.synced{padding:16px;border-radius:13px;background:#edf5da;color:#294724;font-weight:800}.links{margin-top:15px}.links a{color:var(--green);text-decoration:none;font-size:12px;margin-right:15px}
    @media(max-width:850px){.hero{align-items:flex-start;flex-direction:column}.layout{grid-template-columns:1fr}.fields{grid-template-columns:1fr}.wide{grid-column:auto}.nav .links-top{display:none}.workflow{flex-wrap:wrap}}
  </style>
</head>
<body><main class="shell">
  <nav class="nav"><div class="brand"><mark>RELAY</mark> / SALES OPS</div><div class="links-top"><a href="/docs">API</a><a href="https://github.com/ahbilal220/lead-qualification-agent">GITHUB ↗</a></div></nav>
  <section class="hero"><div><div class="eyebrow">Agentic qualification · controlled execution</div><h1>Turn inbound leads into reviewed action.</h1><p>One workflow validates, enriches, scores, and drafts outreach—then stops at a human approval gate before any CRM write.</p></div><div class="guard"><b>✓ Human approval required</b><span>No autonomous external writes</span></div></section>
  <section class="layout">
    <form class="card" id="leadForm"><div class="head"><h2>Lead intake</h2><span class="badge">Live demo</span></div><div class="fields">
      <div><label>Name</label><input name="name" value="Sam Carter" required></div><div><label>Email</label><input name="email" type="email" value="sam@example.com" required></div>
      <div><label>Company</label><input name="company" value="Northstar Logistics" required></div><div><label>Company size</label><input name="company_size" type="number" value="240" min="1" required></div>
      <div><label>Budget (USD)</label><input name="budget_usd" type="number" value="30000" min="0" required></div><div><label>Timeline (days)</label><input name="timeline_days" type="number" value="21" min="1" required></div>
      <div class="wide"><label>Business need</label><textarea name="need" required>Automate inbound lead routing and draft responses for the sales team</textarea></div><div class="wide check"><input name="authority" type="checkbox" checked><span>Contact is a decision-maker</span></div>
    </div><button class="primary" id="qualify" type="submit">Qualify lead</button></form>
    <article class="card result"><div class="head"><h2>Agent workspace</h2><span class="badge" id="status">Waiting</span></div><div class="empty" id="result"><div><b>No lead evaluated yet</b>Submit the sample lead to inspect scoring, outreach, and the approval boundary.</div></div></article>
  </section>
</main>
<script>
let current=null;const form=document.querySelector('#leadForm'),result=document.querySelector('#result'),status=document.querySelector('#status'),button=document.querySelector('#qualify');
const esc=s=>{const e=document.createElement('div');e.textContent=s;return e.innerHTML};
function render(d){current=d;status.textContent=d.status.replaceAll('_',' ');result.className='';const reasons=d.score_reasons.map(x=>`<span class="reason">${esc(x)}</span>`).join('');const audit=d.audit.map(x=>`<div class="audit-item"><b>${esc(x.action.replaceAll('_',' '))}</b> · ${esc(x.detail)}</div>`).join('');const done=d.status==='synced'||d.status==='rejected';result.innerHTML=`<div class="score"><strong>${d.score}</strong><div><b>Qualification score</b><small>Transparent, deterministic reasoning</small></div></div><div class="reasons">${reasons}</div><div class="draft"><b>Draft only — not sent</b><br>${esc(d.outreach_draft||'')}</div><div class="workflow"><span class="node on">Validate</span><span class="arrow">→</span><span class="node on">Enrich</span><span class="arrow">→</span><span class="node on">Score</span><span class="arrow">→</span><span class="node on">Draft</span><span class="arrow">→</span><span class="node ${done?'on':''}">Human gate</span><span class="arrow">→</span><span class="node ${d.status==='synced'?'on':''}">CRM</span></div>${d.status==='synced'?`<div class="synced">✓ Approved and synced to ${esc(d.crm_record_id)}</div>`:d.status==='rejected'?'<div class="synced">Lead rejected. No CRM write occurred.</div>':'<div class="actions"><button onclick="decide(&quot;reject&quot;)">Reject</button><button class="approve" onclick="decide(&quot;approve&quot;)">Approve & sync</button></div>'}<div class="audit">${audit}</div><div class="links"><a href="/docs">Interactive API ↗</a><a href="https://github.com/ahbilal220/lead-qualification-agent">Source code ↗</a></div>`}
form.addEventListener('submit',async e=>{e.preventDefault();button.disabled=true;button.textContent='Agent working…';const x=Object.fromEntries(new FormData(form));x.company_size=Number(x.company_size);x.budget_usd=Number(x.budget_usd);x.timeline_days=Number(x.timeline_days);x.authority=!!x.authority;try{const r=await fetch('/leads',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(x)});render(await r.json())}catch(e){result.className='empty';result.textContent='The demo could not complete this request.'}finally{button.disabled=false;button.textContent='Qualify lead'}});
async function decide(action){const r=await fetch(`/leads/${current.id}/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reviewer:'Portfolio reviewer',note:'Reviewed in interactive demo.'})});render(await r.json())}
if(new URLSearchParams(location.search).has('preview'))setTimeout(()=>form.requestSubmit(),150);
</script></body></html>"""
